const TAG_NAMES: Record<string, string> = { POC: "Point of control", VAH: "Value area high", VAL: "Value area low", sVWAP: "Session VWAP", wVWAP: "Weekly VWAP", "W VWAP": "Weekly VWAP", "7dVWAP": "7-day VWAP", dOpen: "Daily open", "D open": "Daily open", wOpen: "Weekly open", "W open": "Weekly open", mOpen: "Monthly open", "M open": "Monthly open", ES: "S&P 500 futures (ES)", TL: "Trendline support (4h higher lows)", "TL↗": "Auto trend support", "TL↘": "Auto trend resistance", "Ch up": "Channel upper rail", "Ch low": "Channel lower rail", Entry: "Setup entry", Stop: "Setup stop", T1: "Target 1", T2: "Target 2", T3: "Target 3" };
function tagName(lbl: string, txt?: string): string {
const l = String(lbl || "");
if (/^K\d{4,6}$/.test(l)) return "Kyle level";
if (/^S\d$/.test(l)) return `Support ${l} (computed)`;
if (/^[01](\.\d+)?$/.test(l)) return `Fibonacci ${l}`;
if (/^D\d+'?$/.test(l)) return `Your drawn channel ${l}`;
const parts = l.split("+").map((p) => TAG_NAMES[p] || p);
const nm = parts.join(" + ");
if (txt && nm === l) { const t = String(txt).replace(/\s[\d.,]+k?$/, ""); if (t.length > l.length) return t; }
return nm || "Level";
}
function Sheet({ open, onClose, title, children }: { open: boolean; onClose: () => void; title: string; children?: any }) {
if (!open) return null;
return <SheetIn onClose={onClose} title={title}>{children}</SheetIn>;
}
