{series.map((s) => { const v = hv === null ? lastFin(s.v) : s.v[at]; return (<span key={s.name} style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><span style={{ width: 12, height: 0, borderTop: `${s.dash ? "2px dashed" : "3px solid"} ${s.color}`, display: "inline-block" }} />{s.name} <b style={{ color: c.t1, fontWeight: 650, fontVariantNumeric: "tabular-nums" }}>{ok(v) ? `${f(v)}${unit}` : "–"}</b></span>); })}
