const vals = [s.stop, s.entry, ...s.t, price, s.zlo, s.zhi];
let lo = Math.min(...vals), hi = Math.max(...vals); const pad = (hi - lo) * 0.04; lo -= pad; hi += pad;
const X = (v: number) => pl + ((v - lo) / (hi - lo)) * (W - pl - pr);
const tgt = s.t[s.t.length - 1];
const pts = [{ v: s.stop, l: "Stop", col: c.dn }, { v: s.entry, l: "Entry", col: c.t1 }, ...s.t.map((v, i) => ({ v, l: `T${i + 1}`, col: c.up }))];
