const n = labels.length, H = big ? Math.max(h, Math.round(vh * 0.86) - 100) : h, pl = 8, pr = 64, pt = 12, pb = 28, pw = Math.max(50, W - pl - pr), ph = H - pt - pb;
const z = useZoom(-0.5, n - 0.5, `${n}:${labels[0]}`, { W, H, pl, pw, min: Math.min(n, 3), always: big });
const cid = useRef(`zb${Math.random().toString(36).slice(2, 8)}`).current;
