const n = rows.length;
const H = big ? Math.round(vh * 0.86) - 100 : 300, pl = 8, pr = 64, pt = 12, pb = 28, pw = Math.max(50, W - pl - pr), ph = H - pt - pb;
const lo0 = n ? Math.min(...rows.map((r) => r[0])) : 0, hi0 = n ? Math.max(...rows.map((r) => r[0])) : 1;
