// v1.3.6: declutter the main chart: merge levels within 0.1% into one tag, keep only the N nearest to price, fade the far ones
function declutter(ls: Ln[], price: number, max: number): Ln[] {
const out: Ln[] = [];
for (const l of ls) { if (!ok(l.px)) continue; const m = out.find((o) => Math.abs(o.px - l.px) / l.px < 0.001); if (m) { if (!String(m.label).includes(String(l.label))) (m as any).label = `${m.label}/${l.label}`; (m as any).txt = undefined; } else out.push({ ...l }); }
out.sort((a, b) => Math.abs(a.px - price) - Math.abs(b.px - price));
return out.slice(0, max).map((l) => (Math.abs(l.px / price - 1) > 0.015 ? { ...l, op: ((l as any).op ?? 0.9) * 0.45 } : l));
}
