<div style={{ fontSize: 12.5, color: c.t3, marginTop: 4 }}>{`Read from K1m6a's YouTube stream (Coinwise panels) · frame ${s.frame_at ?? "?"}${s.age_min != null ? ` · ${s.age_min} min old` : ""}${s.stale ? " · stale (capture blocked)" : ""} · tap to enlarge. Mods note this feed can lag.`}</div>
{view ? <ImgViewer src={view.src} alt={view.t} title={`${view.t} · K1m6a stream · ${s.frame_at ?? ""}`} w={view.w} h={view.h} onClose={() => setView(null)} /> : null}
