function MacdPanel({ M, K, tf, X }: { M: any; K: number[][]; tf: string; X: any[] }) {
const c = useC(); const [box, W] = useBox(900);
const n = Math.min(K.length, (M.hist || []).length); const i0 = Math.max(0, n - 120);
const H = 110, pl = 4, pr = 56, pt = 8, pb = 14;
const vals = [...M.macd.slice(i0, n), ...M.sig.slice(i0, n), ...M.hist.slice(i0, n)].filter((v: any) => v != null) as number[];
if (!vals.length) return null;
const mx = Math.max(...vals.map((v) => Math.abs(v))) || 1; const pw = W - pl - pr, bw = pw / (n - i0);
const X_ = (i: number) => pl + (i - i0 + 0.5) * bw, Y = (v: number) => pt + (1 - (v + mx) / (2 * mx)) * (H - pt - pb);
const line = (a: any[]) => a.slice(i0, n).map((v, j) => (v == null ? "" : `${j && a[i0 + j - 1] != null ? "L" : "M"}${X_(i0 + j).toFixed(1)},${Y(v).toFixed(1)}`)).join("");
const xs = (X || []).filter((x: any) => x.macd && x.tf === tf && x.t >= K[i0][0]);
const last = (M.macd as any[])[n - 1], sg = (M.sig as any[])[n - 1];
return <div ref={box} data-macd style={{ border: `1px solid ${c.grid}`, borderRadius: 10, padding: "4px 6px" }}>
<div style={{ display: "flex", gap: 10, fontSize: 12, color: c.t3, alignItems: "baseline" }}><b style={{ color: c.t2 }}>{`MACD (12,26,9) · ${tf}`}</b><span style={{ color: c.acc }}>{`MACD ${last ?? "–"}`}</span><span style={{ color: c.amb }}>{`signal ${sg ?? "–"}`}</span><span style={{ marginLeft: "auto" }}>last 120 bars · ▲▼ = signal / zero crosses</span></div>
<svg width={W} height={H} style={{ display: "block" }}>
<line x1={pl} x2={pl + pw} y1={Y(0)} y2={Y(0)} stroke={c.line} strokeDasharray="2 3" />
{(M.hist as any[]).slice(i0, n).map((v, j) => v == null ? null : <rect key={j} x={X_(i0 + j) - bw * 0.3} width={Math.max(1, bw * 0.6)} y={Math.min(Y(0), Y(v))} height={Math.max(0.5, Math.abs(Y(v) - Y(0)))} fill={v >= 0 ? c.up : c.dn} fillOpacity={0.55} />)}
<path d={line(M.macd)} fill="none" stroke={c.acc} strokeWidth={1.3} /><path d={line(M.sig)} fill="none" stroke={c.amb} strokeWidth={1.1} />
{xs.map((x: any, j: number) => { const i = K.findIndex((r) => r[0] === x.t); if (i < i0) return null; return <g key={j}><line x1={X_(i)} x2={X_(i)} y1={pt} y2={H - pb} stroke={x.type === "macd_bull" ? c.up : c.dn} strokeDasharray="1 3" strokeOpacity={0.7} /><text x={X_(i)} y={H - 3} fontSize={10} textAnchor="middle" fill={x.type === "macd_bull" ? c.up : c.dn}>{x.zero ? "0" : x.type === "macd_bull" ? "▲" : "▼"}</text></g>; })}
<text x={W - pr + 4} y={Y(0) + 4} fontSize={11} fill={c.t3}>0</text><text x={W - pr + 4} y={pt + 8} fontSize={11} fill={c.t3}>{`+${Math.round(mx)}`}</text><text x={W - pr + 4} y={H - pb} fontSize={11} fill={c.t3}>{`−${Math.round(mx)}`}</text>
</svg>
</div>;
}
