const shellRef = useRef<any>(null), scRef = useRef<any>(null);
const [shellH, setShellH] = useState<number>(0);
useEffect(() => {
const fit = () => {
const el = shellRef.current; if (!el) return;
const cs = getComputedStyle(el); const cv = parseFloat(cs.getPropertyValue("--cursor-canvas-viewport-height"));
// v1.3.8: fit to the frame's real visible height only (no screen.availHeight, no 'space after' subtraction) so the bar sits flush on the bottom edge
const ih = window.innerHeight || 800, vv = (window.visualViewport && window.visualViewport.height) || ih;
const base = Math.min(ih, vv); void cv;
const top = el.getBoundingClientRect().top + (window.scrollY || 0);
const h = Math.max(360, Math.floor(base - top));
setShellH((p: number) => (Math.abs(p - h) > 2 ? h : p));
if (window.scrollY) window.scrollTo(0, 0);
try { el.style.setProperty("--bd-padb", `${parseFloat(getComputedStyle(document.body).paddingBottom) || 0}px`); } catch (_) { /* ignore */ }
};
fit(); const t = setTimeout(fit, 300), t2 = setTimeout(fit, 1200);
window.addEventListener("resize", fit); if (window.visualViewport) window.visualViewport.addEventListener("resize", fit);
return () => { clearTimeout(t); clearTimeout(t2); window.removeEventListener("resize", fit); if (window.visualViewport) window.visualViewport.removeEventListener("resize", fit); };
}, []);
const [scale, setScaleS] = useState<number>(() => Number(lsGet("bd-scale", 1)) || 1);
const setScale = (v: number) => { setScaleS(v); lsSet("bd-scale", v); };
