const kc = (key: string): number[][] => { const o = V.candles[key]; if (!o) return []; const ts = tx(o.t, o.k.length); return o.k.map((r: number[], i: number) => [ts[i], ...r]); };
const K: number[][] = kc(tf);
// v1.5.0: moving averages (EMA default / SMA) + MACD toggle
