const [maOn, setMaOn] = useState<any>({ 9: false, 20: false, 50: true, 100: false, 200: true });
const [macdOn, setMacdOn] = useState<boolean>(false);
const MAS: any = D.ma && D.ma.series ? D.ma.series[tf] : null;
const maCol = (n: number): string => (n === 9 ? `color-mix(in srgb, ${c.t1} 55%, ${c.acc})` : n === 20 ? c.acc : n === 50 ? `color-mix(in srgb, ${c.amb} 75%, ${c.t1})` : n === 100 ? `color-mix(in srgb, ${c.acc} 45%, ${c.dn})` : c.t1);
const maSer: Ser[] = MAS ? [9, 20, 50, 100, 200].filter((n) => maOn[n] && MAS[maType] && MAS[maType][String(n)]).map((n) => ({ name: `${maType.toUpperCase()} ${n}`, color: maCol(n), v: MAS[maType][String(n)] as Num[], thin: true })) : [];
const xMk: Mark[] = D.ma ? (D.ma.crosses as any[]).filter((x) => x.tf === tf && (x.macd ? macdOn : maOn[x.f] && maOn[x.s]) && maType === "ema").slice(0, 8).map((x) => ({ t: x.t, px: x.price, txt: x.label, hi: /death|bear/.test(x.type) })) : [];
const pm = (V.patMarks as any[]).filter((m) => m.tf === tf && m.t).map((m) => ({ t: m.t, px: m.px, txt: m.txt, hi: m.hi }));
const [patOn, setPatOn] = useState<boolean>(false);
