const spLines: Ln[] = spOn && D.sp ? ((D.sp.zones || []) as any[]).slice(0, 3).flatMap((z) => [{ px: z.hi, label: z.label || `SP ${lvK(z.lo)}–${lvK(z.hi)}`, color: c.acc, dash: "1 3", sw: 1, op: 0.85 }, { px: z.lo, label: "", color: c.acc, dash: "1 3", sw: 1, op: 0.85, hideLbl: true }]) : [];
const rvMk: Mark[] = D.rev ? (D.rev.signals as any[]).filter((x) => x.status !== "failed" && x.timeframe === tf && x.level && x.t && x.type !== "htf_hidden_divergence" && x.type !== "fear_greed").slice(0, 5).map((x) => ({ t: x.t, px: x.level, txt: `↺ ${(RV_NM[x.type] || "").split(" ")[0]}`, hi: x.direction === "bear" })) : [];
const marks: Mark[] = [...(V.marks[tf] ?? []), ...pm, ...patMk, ...xMk, ...rvMk];
