<Kpi label="24h liquidations · OKX" value={`${usd(D.liqTot["24h"].long)} L`} sub={`shorts ${usd(D.liqTot["24h"].short)}`} color={c.dn} />
{X.opt ? <Kpi label="Put/call OI · Deribit" value={nd(X.opt.pcr, 2)} sub={`max pain ${n0(X.opt.major?.max_pain ?? null)} (${X.opt.major?.expiry ?? ""})`} /> : null}
